import channels_graphql_ws
import graphene
from graphql import GraphQLError
from .models import Document, DocumentCollaborator
from .types import CursorActivityType

class DocumentPresenceSubscription(channels_graphql_ws.Subscription):
    activity = graphene.Field(CursorActivityType)

    class Arguments:
        doc_uuid = graphene.String(required=True)

    @classmethod
    def subscribe(cls, root, info, doc_uuid):
        user = info.context.user
        if not user.is_authenticated:
            raise GraphQLError("Login required")

        doc = Document.objects.filter(uuid=doc_uuid).first()
        if not doc or (doc.owner != user and not DocumentCollaborator.objects.filter(document=doc, user=user).exists()):
            raise GraphQLError("Document access unauthorized")

        return [f"doc_presence_{doc_uuid}"]

    @classmethod
    def publish(cls, payload, info, doc_uuid):
        return cls(activity=payload.get("cursor_event"))
